-- 095_payment_paid_tracking.sql
BEGIN;
CREATE TABLE IF NOT EXISTS public.project_payment_tracking_events(
 id uuid PRIMARY KEY,certification_case_id uuid NOT NULL REFERENCES public.project_payment_certification_cases(id)ON DELETE RESTRICT,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,event_number integer NOT NULL CHECK(event_number>0),event_type text NOT NULL CHECK(event_type IN('SENT_FOR_PAYMENT','PAYMENT_RECEIVED')),amount numeric(24,2)NOT NULL CHECK(amount>0),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),external_reference text NOT NULL CHECK(btrim(external_reference)<>''AND char_length(external_reference)<=500),event_date date NOT NULL,event_note text NOT NULL CHECK(char_length(event_note)<=3000),recorded_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,recorded_at timestamptz NOT NULL DEFAULT now(),UNIQUE(certification_case_id,event_number)
);
CREATE OR REPLACE FUNCTION private.prevent_payment_tracking_event_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'PAYMENT_TRACKING_EVENT_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS payment_tracking_event_immutable ON public.project_payment_tracking_events;CREATE TRIGGER payment_tracking_event_immutable BEFORE UPDATE OR DELETE ON public.project_payment_tracking_events FOR EACH ROW EXECUTE FUNCTION private.prevent_payment_tracking_event_mutation();
ALTER TABLE public.project_payment_tracking_events ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS payment_tracking_events_select ON public.project_payment_tracking_events;CREATE POLICY payment_tracking_events_select ON public.project_payment_tracking_events FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_payment_tracking_events FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_payment_tracking_events TO authenticated;
CREATE OR REPLACE FUNCTION public.record_payment_tracking_event(p_certification_case_id uuid,p_event_id uuid,p_event_type text,p_amount numeric,p_external_reference text,p_event_date date,p_event_note text,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();v_role text;c public.project_payment_certification_cases%ROWTYPE;m public.project_payment_milestones%ROWTYPE;s public.project_payment_schedules%ROWTYPE;req public.write_command_requests%ROWTYPE;kind text:=upper(btrim(COALESCE(p_event_type,'')));certified numeric;paid_before numeric;paid_after numeric;event_no integer;next_status text;result jsonb;
BEGIN SELECT upper(p.role)INTO v_role FROM public.profiles p WHERE p.id=u;SELECT *INTO c FROM public.project_payment_certification_cases WHERE id=p_certification_case_id FOR UPDATE;IF c.id IS NULL THEN RAISE EXCEPTION'PAYMENT_CERTIFICATION_CASE_NOT_FOUND'USING ERRCODE='P0002';END IF;SELECT *INTO m FROM public.project_payment_milestones WHERE id=c.milestone_id FOR UPDATE;SELECT *INTO s FROM public.project_payment_schedules WHERE id=m.payment_schedule_id;IF u IS NULL OR v_role NOT IN('PM','ADMIN')OR public.can_write_project(c.project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_TRACKING_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_event_id IS NULL OR p_client_request_id IS NULL OR kind NOT IN('SENT_FOR_PAYMENT','PAYMENT_RECEIVED')OR COALESCE(p_amount,0)<=0 OR btrim(COALESCE(p_external_reference,''))=''OR char_length(p_external_reference)>500 OR p_event_date IS NULL OR char_length(COALESCE(p_event_note,''))>3000 THEN RAISE EXCEPTION'INVALID_PAYMENT_TRACKING_COMMAND'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'payment_tracking.record',p_client_request_id,c.project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='payment_tracking.record'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;SELECT certified_amount INTO certified FROM public.project_payment_certification_decisions WHERE certification_case_id=c.id AND decision_type IN('FULL','PARTIAL')ORDER BY decision_number DESC LIMIT 1;IF certified IS NULL THEN RAISE EXCEPTION'PAYMENT_REQUIRES_CERTIFIED_AMOUNT'USING ERRCODE='55000';END IF;SELECT COALESCE(sum(amount),0)INTO paid_before FROM public.project_payment_tracking_events WHERE certification_case_id=c.id AND event_type='PAYMENT_RECEIVED';IF kind='SENT_FOR_PAYMENT'AND(c.status NOT IN('APPROVED','PARTIALLY_APPROVED')OR p_amount<>certified OR EXISTS(SELECT 1 FROM public.project_payment_tracking_events WHERE certification_case_id=c.id AND event_type='SENT_FOR_PAYMENT'))THEN RAISE EXCEPTION'INVALID_SEND_FOR_PAYMENT_STATE_OR_AMOUNT'USING ERRCODE='55000';ELSIF kind='PAYMENT_RECEIVED'AND(c.status<>'SENT_FOR_PAYMENT'OR paid_before+p_amount>certified)THEN RAISE EXCEPTION'INVALID_PAYMENT_RECEIPT_STATE_OR_AMOUNT'USING ERRCODE='55000';END IF;SELECT COALESCE(max(event_number),0)+1 INTO event_no FROM public.project_payment_tracking_events WHERE certification_case_id=c.id;INSERT INTO public.project_payment_tracking_events VALUES(p_event_id,c.id,c.project_id,event_no,kind,p_amount,s.currency_code,btrim(p_external_reference),p_event_date,btrim(COALESCE(p_event_note,'')),u,now());paid_after:=paid_before+CASE WHEN kind='PAYMENT_RECEIVED'THEN p_amount ELSE 0 END;next_status:=CASE WHEN kind='SENT_FOR_PAYMENT'THEN'SENT_FOR_PAYMENT'WHEN paid_after=certified THEN'PAID'ELSE'SENT_FOR_PAYMENT'END;UPDATE public.project_payment_certification_cases SET status=next_status WHERE id=c.id;UPDATE public.project_payment_milestones SET status=next_status WHERE id=m.id;result:=jsonb_build_object('eventId',p_event_id,'eventNumber',event_no,'eventType',kind,'caseStatus',next_status,'certifiedAmount',certified,'paidAmount',paid_after,'outstandingAmount',certified-paid_after,'currencyCode',s.currency_code);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_project_payment_tracking(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PAYMENT_TRACKING_FORBIDDEN'USING ERRCODE='42501';END IF;RETURN jsonb_build_object('projectId',p_project_id,'payments',COALESCE((SELECT jsonb_agg(jsonb_build_object('certificationCaseId',c.id,'caseNumber',c.case_number,'caseStatus',c.status,'milestoneTitle',m.title,'currencyCode',s.currency_code,'certifiedAmount',d.certified_amount,'paidAmount',COALESCE(x.paid_amount,0),'outstandingAmount',d.certified_amount-COALESCE(x.paid_amount,0),'events',COALESCE(x.events,'[]'::jsonb))ORDER BY c.case_number DESC)FROM public.project_payment_certification_cases c JOIN public.project_payment_milestones m ON m.id=c.milestone_id JOIN public.project_payment_schedules s ON s.id=m.payment_schedule_id JOIN LATERAL(SELECT certified_amount FROM public.project_payment_certification_decisions WHERE certification_case_id=c.id AND decision_type IN('FULL','PARTIAL')ORDER BY decision_number DESC LIMIT 1)d ON true LEFT JOIN LATERAL(SELECT sum(amount)FILTER(WHERE event_type='PAYMENT_RECEIVED')paid_amount,jsonb_agg(jsonb_build_object('eventId',id,'eventNumber',event_number,'eventType',event_type,'amount',amount,'externalReference',external_reference,'eventDate',event_date,'eventNote',event_note,'recordedAt',recorded_at)ORDER BY event_number)events FROM public.project_payment_tracking_events WHERE certification_case_id=c.id)x ON true WHERE c.project_id=p_project_id),'[]'::jsonb));END;$$;
REVOKE ALL ON FUNCTION private.prevent_payment_tracking_event_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.record_payment_tracking_event(uuid,uuid,text,numeric,text,date,text,uuid),public.get_project_payment_tracking(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.record_payment_tracking_event(uuid,uuid,text,numeric,text,date,text,uuid),public.get_project_payment_tracking(bigint)TO authenticated;
COMMIT;
